// Scenario starts (DESIGN §19). The co-op's past is generated by the prudent baseline GM from
// an earlier year with a fixed seed; the player takes over at the scenario date. Goals are
// judged at the deadline (see SCENARIOS).

import { SCENARIOS, type ScenarioDef, type ScenarioGoal } from '../../data/scenarios';
import { fiscalYearOf, toMonthIndex } from '../core/calendar';
import { balanceSheet } from '../ledger/statements';
import type { TickContext } from './context';
import type { GameState } from '../types';
import { advanceMonth } from './advance';
import { DEFAULT_SETUP, newGame } from './newGame';
import { POLICIES } from './policies';

export const scenarioById = (id: string | undefined): ScenarioDef | undefined => SCENARIOS.find((x) => x.id === id);

/** Build the scenario's co-op: its history, then the handover. */
export function newScenario(id: string): GameState {
  const sc = scenarioById(id);
  if (!sc) throw new Error(`Unknown scenario ${id}`);
  const h = sc.history;
  let s = newGame({ ...DEFAULT_SETUP, startYear: h.fromYear, startingMembers: h.members, gameSeed: h.seed, mapSeed: h.mapSeed, capitalPreset: h.capital, historyMode: 'strict', scenarioId: sc.id });
  const handover = toMonthIndex(sc.year, 1);
  while (s.clock.monthIndex < handover - 1 && !s.outcome) s = advanceMonth(s, POLICIES.baseline(s)).state;
  if (s.outcome) throw new Error(`Scenario ${id} history ended early (${s.outcome.kind}); adjust its seed.`);
  // The handover: history read, a new GM, the briefing.
  s = { ...s, inbox: s.inbox.map((i) => ({ ...i, read: true })), deals: s.deals.filter((d) => d.stage === 'closed' || d.stage === 'dead') };
  s.clock = { ...s.clock, startMonth: s.clock.monthIndex + 1 };
  if (sc.weakNeighbors) {
    s.competitors = s.competitors.map((c) => (c.kind === 'coop' && c.status === 'active' && (c.sites[0]?.division ?? 'GRAIN') === 'GRAIN' ? { ...c, strength: Math.min(c.strength ?? 50, 40) } : c));
  }
  s.governance = { ...s.governance, boardConfidence: 65, pip: false };
  s.inbox.push({
    id: s.nextInboxId++, monthIndex: s.clock.monthIndex, read: false, kind: 'memo', title: `Scenario: ${sc.title}`,
    body: `${sc.briefing}\n\nGoals, judged in January ${sc.deadlineYear}:\n${sc.goals.map((g) => `• ${g.label}`).join('\n')}\n\nThe co-op's past annual reports are on the Reports screen. Your goals and progress are on the Dashboard.`,
  });
  return s;
}

export interface GoalStatus {
  label: string;
  met: boolean;
  detail: string;
}

function grainInFy(s: GameState, fy: number): number {
  return s.reports.find((r) => r.fy === fy)?.grainBu ?? 0;
}

function judge(s: GameState, sc: ScenarioDef, g: ScenarioGoal): GoalStatus {
  const bs = balanceSheet(s.ledger, s.clock.monthIndex);
  switch (g.kind) {
    case 'survive': return { label: g.label, met: !s.outcome, detail: s.outcome ? s.outcome.kind : 'in business' };
    case 'standing': return { label: g.label, met: s.coop.finance.status === 'standard', detail: s.coop.finance.status };
    case 'equityRatio': {
      const r = bs.totalAssets > 0 ? bs.totalEquity / bs.totalAssets : 0;
      return { label: g.label, met: r >= g.min, detail: `${Math.round(r * 100)}% now` };
    }
    case 'locations': {
      const n = s.coop.facilities.filter((f) => f.status !== 'closed').length;
      return { label: g.label, met: n >= g.min, detail: `${n} now` };
    }
    case 'merger': {
      const n = s.deals.filter((d) => d.kind === 'merger' && (d.stage === 'closed' || d.stage === 'integration') && d.startedMonth >= s.clock.startMonth).length;
      return { label: g.label, met: n > 0, detail: `${n} completed` };
    }
    case 'grainGrowth': {
      const base = grainInFy(s, sc.year - 1);
      const now = grainInFy(s, sc.deadlineYear - 1) || (s.reports[s.reports.length - 1]?.grainBu ?? 0);
      const g0 = base > 0 ? now / base - 1 : 0;
      return { label: g.label, met: base > 0 && g0 >= g.min, detail: `${g0 >= 0 ? '+' : ''}${Math.round(g0 * 100)}% so far` };
    }
    case 'savingsYears': {
      const yrs = s.reports.filter((r) => r.fy >= sc.year && r.fy <= sc.deadlineYear - 1 && r.savingsBeforeTax > 0).length;
      return { label: g.label, met: yrs >= g.years, detail: `${yrs} so far` };
    }
  }
}

/** Progress on the scenario's goals (null outside a scenario). */
export function scenarioGoals(s: GameState): { def: ScenarioDef; goals: GoalStatus[]; judged: boolean } | null {
  const sc = scenarioById(s.setup.scenarioId);
  if (!sc) return null;
  return { def: sc, goals: sc.goals.map((g) => judge(s, sc, g)), judged: s.clock.monthIndex >= toMonthIndex(sc.deadlineYear, 1) };
}

/** At the deadline, the board reports how the scenario went (once). */
export function stepScenario(ctx: TickContext): void {
  const sc = scenarioById(ctx.state.setup.scenarioId);
  if (!sc || ctx.mi !== toMonthIndex(sc.deadlineYear, 1)) return;
  const r = scenarioGoals(ctx.state)!;
  const met = r.goals.filter((g) => g.met).length;
  ctx.inbox({
    kind: 'alert', title: `Scenario complete: ${met} of ${r.goals.length} goals met`,
    body: `${sc.title}, judged in January ${sc.deadlineYear}:\n${r.goals.map((g) => `${g.met ? '✓' : '✗'} ${g.label} (${g.detail})`).join('\n')}\n\n${met === r.goals.length ? 'The board and the members thank you: a job well done.' : 'The co-op carries on; you can keep playing for as long as the data runs.'} Fiscal year ${fiscalYearOf(ctx.mi, ctx.state.setup.fiscalYearEndMonth)} continues.`,
  });
}
